  for (const [c, t] of Object.entries(columns)) {
    every[c] = { params: [], returns: t };
    if (t === "f64") numeric[c] = { params: [], returns: "f64" };
  }
  const sameType = {};
  for (const [c, t] of Object.entries(columns)) sameType[c] = { params: [], returns: t };
