  step(state, call, inferred) {
    const a = call.args;
    switch (call.slot) {
      case "derive": return { ...state, columns: { ...state.columns, [a[0]]: inferred } };
      case "rename": {
        const columns = {};
        for (const [c, t] of Object.entries(state.columns)) columns[a[0][c] ?? c] = t;
